-- MVP-070A (Issue #128): weekly DRAFT timesheets generated by a tenant administrator with exact MFA
-- for one site and one site-local week (Monday 00:00 to the next Monday 00:00 in the site's time
-- zone), from the operational schedules, their effective assignees and the effective attendance
-- projection (MVP-062). Drafts and their rows are evidence: refreshed only as a new append-only
-- revision; never submitted, approved, priced or exported in this story.
--
-- Ownership: the people module; only the bounded com.divalhr.core.people.schedule package reads
-- or writes these objects (ADR 0018).
--
-- Classification: Restricted HR/Operations (worked time per employee). No name, label or time
-- leaves this schema through audit metadata, events, logs or errors.
--
-- Shape (T70A-8):
--   * people.timesheet_generation: one per tenant, site and local Monday (_site_week_unique); the
--     week, the site's time zone and the exact UTC boundaries as generated; the run version (1 when
--     generated, + 1 for each refresh); DRAFT only. The single permitted update is a refresh
--     (timesheet_generation_guard): version + 1 and the refresh instant and subject, nothing else.
--   * people.timesheet: one per tenant, employee, site and local Monday (_employee_week_unique),
--     DRAFT only, with its current revision and that revision's totals: a composite key to the
--     revision header (_current, deferred) makes the totals exactly the current revision's. The
--     single permitted update moves to the next revision (timesheet_guard).
--   * people.timesheet_revision: append-only headers, numbered 1, 2, ... per timesheet (the guard
--     requires the previous revision), with the generation version, the source digest and totals.
--   * people.timesheet_row: append-only rows of one revision, one per slot, with the snapshot of
--     the slot (composite key to the immutable slot instants), the employee's qualifying
--     employment, site and cost center, the bilingual label, the effective attendance record and
--     its effective instants and correction version, the state and the worked minutes. The state
--     fixes the shape exactly (_shape): READY (completed attendance; worked minutes are the whole
--     minutes between the effective instants, truncated), MISSING_ATTENDANCE (no record),
--     OPEN_ATTENDANCE (no effective check-out) and SOURCE_CHANGED (a slot of the previous revision
--     that is no longer included); only READY rows have worked minutes.
--   * deferred (timesheet_revision_exact): every revision's totals are exactly its rows' counts
--     and sum; a timesheet's current revision is its latest.
-- Attendance events, attendance corrections, schedules, employment history and leave evidence are
-- referenced, never changed.
--
-- Indexes: timesheet_generation_site_week_unique (a site's week); timesheet_generation_member
-- (a generation's drafts); timesheet_employee_week (an employee's drafts, newest week first);
-- the row and revision primary keys (a revision's rows, a timesheet's revisions).
--
-- Rollback: db/rollback/V32__rollback.sql (manual, never run by Flyway) restores V31 exactly only
-- while no generation, timesheet, revision or row exists; there is no override.

-- ---------------------------------------------------------------------------------------------
-- Generations (one per site and week)
-- ---------------------------------------------------------------------------------------------

CREATE TABLE people.timesheet_generation (
    tenant_id       uuid        NOT NULL,
    id              uuid        NOT NULL,
    site_id         uuid        NOT NULL,
    week_start      date        NOT NULL,
    week_end        date        NOT NULL,
    site_timezone   text        NOT NULL,
    period_start_at timestamptz NOT NULL,
    period_end_at   timestamptz NOT NULL,
    version         integer     NOT NULL,
    status          text        NOT NULL,
    generated_at    timestamptz NOT NULL,
    generated_by    text        NOT NULL,
    refreshed_at    timestamptz,
    refreshed_by    text,
    CONSTRAINT timesheet_generation_pkey PRIMARY KEY (tenant_id, id),
    CONSTRAINT timesheet_generation_site_week_unique UNIQUE (tenant_id, site_id, week_start),
    CONSTRAINT timesheet_generation_member_key UNIQUE (tenant_id, id, site_id, week_start),
    -- ADR 0018: the database-level site key is the documented integrity exception (as ADR 0014).
    CONSTRAINT timesheet_generation_site
        FOREIGN KEY (tenant_id, site_id) REFERENCES tenant.site (tenant_id, id),
    CONSTRAINT timesheet_generation_week
        CHECK (EXTRACT(ISODOW FROM week_start) = 1 AND week_end = week_start + 7
            AND week_start BETWEEN DATE '2000-01-03' AND DATE '2999-12-30'),
    CONSTRAINT timesheet_generation_timezone_format
        CHECK (site_timezone ~ '^[A-Za-z][A-Za-z0-9_+-]*(/[A-Za-z0-9_+-]+){0,2}$'
            AND char_length(site_timezone) BETWEEN 3 AND 64),
    -- Seven local days: 168 hours, give or take a daylight-saving change.
    CONSTRAINT timesheet_generation_period
        CHECK (period_end_at - period_start_at BETWEEN INTERVAL '166 hours' AND INTERVAL '170 hours'),
    CONSTRAINT timesheet_generation_version CHECK (version >= 1),
    CONSTRAINT timesheet_generation_status CHECK (status = 'DRAFT'),
    CONSTRAINT timesheet_generation_refresh_shape
        CHECK ((version = 1) = (refreshed_at IS NULL)
            AND (refreshed_at IS NULL) = (refreshed_by IS NULL)
            AND (refreshed_at IS NULL OR refreshed_at >= generated_at)),
    CONSTRAINT timesheet_generation_subjects
        CHECK (char_length(generated_by) BETWEEN 1 AND 255
            AND (refreshed_by IS NULL OR char_length(refreshed_by) BETWEEN 1 AND 255))
);

COMMENT ON TABLE people.timesheet_generation IS
    'MVP-070A weekly site timesheet run (Restricted HR/Operations): the site-local week, its exact UTC boundaries and the run version; refreshed only by a new version.';

-- ---------------------------------------------------------------------------------------------
-- Timesheets (one per employee, site and week) and their append-only revisions and rows
-- ---------------------------------------------------------------------------------------------

CREATE TABLE people.timesheet (
    tenant_id        uuid        NOT NULL,
    id               uuid        NOT NULL,
    generation_id    uuid        NOT NULL,
    employee_id      uuid        NOT NULL,
    site_id          uuid        NOT NULL,
    week_start       date        NOT NULL,
    status           text        NOT NULL,
    current_revision integer     NOT NULL,
    row_count        integer     NOT NULL,
    ready_rows       integer     NOT NULL,
    missing_rows     integer     NOT NULL,
    open_rows        integer     NOT NULL,
    changed_rows     integer     NOT NULL,
    worked_minutes   integer     NOT NULL,
    created_at       timestamptz NOT NULL,
    updated_at       timestamptz NOT NULL,
    CONSTRAINT timesheet_pkey PRIMARY KEY (tenant_id, id),
    CONSTRAINT timesheet_employee_week_unique UNIQUE (tenant_id, employee_id, site_id, week_start),
    CONSTRAINT timesheet_row_owner_key UNIQUE (tenant_id, id, employee_id, site_id),
    CONSTRAINT timesheet_generation_ref
        FOREIGN KEY (tenant_id, generation_id, site_id, week_start)
            REFERENCES people.timesheet_generation (tenant_id, id, site_id, week_start),
    CONSTRAINT timesheet_employee
        FOREIGN KEY (tenant_id, employee_id) REFERENCES people.employee (tenant_id, id),
    CONSTRAINT timesheet_status CHECK (status = 'DRAFT'),
    CONSTRAINT timesheet_revision_positive CHECK (current_revision >= 1),
    CONSTRAINT timesheet_totals
        CHECK (ready_rows >= 0 AND missing_rows >= 0 AND open_rows >= 0 AND changed_rows >= 0
            AND row_count >= 1
            AND row_count = ready_rows + missing_rows + open_rows + changed_rows
            AND worked_minutes >= 0 AND (ready_rows > 0 OR worked_minutes = 0)),
    CONSTRAINT timesheet_updated CHECK (updated_at >= created_at)
);

COMMENT ON TABLE people.timesheet IS
    'MVP-070A weekly draft timesheet of one employee at one site (Restricted HR/Operations): the current revision and exactly its totals.';

CREATE INDEX timesheet_employee_week
    ON people.timesheet (tenant_id, employee_id, week_start DESC, id DESC);
CREATE INDEX timesheet_generation_member
    ON people.timesheet (tenant_id, generation_id, id);

CREATE TABLE people.timesheet_revision (
    tenant_id          uuid        NOT NULL,
    timesheet_id       uuid        NOT NULL,
    revision           integer     NOT NULL,
    generation_version integer     NOT NULL,
    source_digest      text        NOT NULL,
    row_count          integer     NOT NULL,
    ready_rows         integer     NOT NULL,
    missing_rows       integer     NOT NULL,
    open_rows          integer     NOT NULL,
    changed_rows       integer     NOT NULL,
    worked_minutes     integer     NOT NULL,
    created_at         timestamptz NOT NULL,
    CONSTRAINT timesheet_revision_pkey PRIMARY KEY (tenant_id, timesheet_id, revision),
    CONSTRAINT timesheet_revision_totals_key UNIQUE (tenant_id, timesheet_id, revision, row_count,
        ready_rows, missing_rows, open_rows, changed_rows, worked_minutes),
    CONSTRAINT timesheet_revision_timesheet
        FOREIGN KEY (tenant_id, timesheet_id) REFERENCES people.timesheet (tenant_id, id),
    CONSTRAINT timesheet_revision_number CHECK (revision >= 1 AND generation_version >= 1),
    CONSTRAINT timesheet_revision_digest CHECK (source_digest ~ '^[0-9a-f]{64}$'),
    CONSTRAINT timesheet_revision_totals
        CHECK (ready_rows >= 0 AND missing_rows >= 0 AND open_rows >= 0 AND changed_rows >= 0
            AND row_count >= 1
            AND row_count = ready_rows + missing_rows + open_rows + changed_rows
            AND worked_minutes >= 0 AND (ready_rows > 0 OR worked_minutes = 0))
);

COMMENT ON TABLE people.timesheet_revision IS
    'MVP-070A append-only timesheet revision header: numbered per timesheet, the run version, the source digest and the totals of its rows.';

-- The timesheet's totals are exactly its current revision's (checked at commit).
ALTER TABLE people.timesheet
    ADD CONSTRAINT timesheet_current
        FOREIGN KEY (tenant_id, id, current_revision, row_count, ready_rows, missing_rows,
            open_rows, changed_rows, worked_minutes)
            REFERENCES people.timesheet_revision (tenant_id, timesheet_id, revision, row_count,
                ready_rows, missing_rows, open_rows, changed_rows, worked_minutes)
            DEFERRABLE INITIALLY DEFERRED;

CREATE TABLE people.timesheet_row (
    tenant_id            uuid        NOT NULL,
    timesheet_id         uuid        NOT NULL,
    revision             integer     NOT NULL,
    slot_id              uuid        NOT NULL,
    schedule_id          uuid        NOT NULL,
    employee_id          uuid        NOT NULL,
    employment_id        uuid        NOT NULL,
    site_id              uuid        NOT NULL,
    cost_center_id       uuid,
    label_en             text        NOT NULL,
    label_fr             text        NOT NULL,
    scheduled_start_at   timestamptz NOT NULL,
    scheduled_end_at     timestamptz NOT NULL,
    attendance_record_id uuid,
    checked_in_at        timestamptz,
    checked_out_at       timestamptz,
    correction_version   integer,
    state                text        NOT NULL,
    worked_minutes       integer,
    CONSTRAINT timesheet_row_pkey PRIMARY KEY (tenant_id, timesheet_id, revision, slot_id),
    CONSTRAINT timesheet_row_revision
        FOREIGN KEY (tenant_id, timesheet_id, revision)
            REFERENCES people.timesheet_revision (tenant_id, timesheet_id, revision),
    CONSTRAINT timesheet_row_owner
        FOREIGN KEY (tenant_id, timesheet_id, employee_id, site_id)
            REFERENCES people.timesheet (tenant_id, id, employee_id, site_id),
    CONSTRAINT timesheet_row_slot
        FOREIGN KEY (tenant_id, slot_id, schedule_id, scheduled_start_at, scheduled_end_at)
            REFERENCES people.work_schedule_slot (tenant_id, id, schedule_id, start_at, end_at),
    CONSTRAINT timesheet_row_employment
        FOREIGN KEY (tenant_id, employment_id, employee_id)
            REFERENCES people.employment (tenant_id, id, employee_id),
    CONSTRAINT timesheet_row_attendance
        FOREIGN KEY (tenant_id, attendance_record_id)
            REFERENCES people.attendance_record (tenant_id, id),
    CONSTRAINT timesheet_row_state
        CHECK (state IN ('READY', 'MISSING_ATTENDANCE', 'OPEN_ATTENDANCE', 'SOURCE_CHANGED')),
    CONSTRAINT timesheet_row_labels
        CHECK (char_length(label_en) BETWEEN 1 AND 200 AND char_length(label_fr) BETWEEN 1 AND 200),
    CONSTRAINT timesheet_row_schedule_order CHECK (scheduled_end_at > scheduled_start_at),
    CONSTRAINT timesheet_row_shape CHECK (CASE state
        WHEN 'READY' THEN attendance_record_id IS NOT NULL AND checked_in_at IS NOT NULL
            AND checked_out_at IS NOT NULL AND checked_out_at > checked_in_at
            AND correction_version >= 0
            AND worked_minutes
                = floor(EXTRACT(EPOCH FROM (checked_out_at - checked_in_at)) / 60)::integer
        WHEN 'OPEN_ATTENDANCE' THEN attendance_record_id IS NOT NULL AND checked_in_at IS NOT NULL
            AND checked_out_at IS NULL AND correction_version >= 0 AND worked_minutes IS NULL
        ELSE attendance_record_id IS NULL AND checked_in_at IS NULL AND checked_out_at IS NULL
            AND correction_version IS NULL AND worked_minutes IS NULL
        END)
);

COMMENT ON TABLE people.timesheet_row IS
    'MVP-070A append-only timesheet row: the snapshot of one slot and its effective attendance in one revision (Restricted HR/Operations).';

-- ---------------------------------------------------------------------------------------------
-- Guards: append-only evidence, the single permitted updates, contiguous revisions
-- ---------------------------------------------------------------------------------------------

CREATE FUNCTION people.timesheet_immutable() RETURNS trigger
    LANGUAGE plpgsql
AS $fn$
BEGIN
    RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = TG_TABLE_NAME || '_immutable',
        MESSAGE = 'timesheet evidence is never changed or deleted';
END
$fn$;

CREATE FUNCTION people.timesheet_no_truncate() RETURNS trigger
    LANGUAGE plpgsql
AS $fn$
BEGIN
    RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = TG_TABLE_NAME || '_no_truncate',
        MESSAGE = 'timesheet evidence is never truncated';
END
$fn$;

CREATE TRIGGER timesheet_revision_immutable
    BEFORE UPDATE OR DELETE ON people.timesheet_revision
    FOR EACH ROW EXECUTE FUNCTION people.timesheet_immutable();
CREATE TRIGGER timesheet_row_immutable
    BEFORE UPDATE OR DELETE ON people.timesheet_row
    FOR EACH ROW EXECUTE FUNCTION people.timesheet_immutable();
CREATE TRIGGER timesheet_generation_no_truncate
    BEFORE TRUNCATE ON people.timesheet_generation
    FOR EACH STATEMENT EXECUTE FUNCTION people.timesheet_no_truncate();
CREATE TRIGGER timesheet_no_truncate
    BEFORE TRUNCATE ON people.timesheet
    FOR EACH STATEMENT EXECUTE FUNCTION people.timesheet_no_truncate();
CREATE TRIGGER timesheet_revision_no_truncate
    BEFORE TRUNCATE ON people.timesheet_revision
    FOR EACH STATEMENT EXECUTE FUNCTION people.timesheet_no_truncate();
CREATE TRIGGER timesheet_row_no_truncate
    BEFORE TRUNCATE ON people.timesheet_row
    FOR EACH STATEMENT EXECUTE FUNCTION people.timesheet_no_truncate();

-- A generation is inserted at version 1; its only change is a refresh: version + 1 with the
-- refresh instant and subject; never deleted.
CREATE FUNCTION people.timesheet_generation_guard() RETURNS trigger
    LANGUAGE plpgsql
AS $fn$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'timesheet_generation_immutable',
            MESSAGE = 'a timesheet generation is never deleted';
    END IF;
    IF TG_OP = 'INSERT' THEN
        IF NEW.version <> 1 OR NEW.refreshed_at IS NOT NULL THEN
            RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'timesheet_generation_guard',
                MESSAGE = 'a timesheet generation starts at version 1';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id OR NEW.id IS DISTINCT FROM OLD.id
        OR NEW.site_id IS DISTINCT FROM OLD.site_id OR NEW.week_start IS DISTINCT FROM OLD.week_start
        OR NEW.week_end IS DISTINCT FROM OLD.week_end
        OR NEW.site_timezone IS DISTINCT FROM OLD.site_timezone
        OR NEW.period_start_at IS DISTINCT FROM OLD.period_start_at
        OR NEW.period_end_at IS DISTINCT FROM OLD.period_end_at
        OR NEW.status IS DISTINCT FROM OLD.status
        OR NEW.generated_at IS DISTINCT FROM OLD.generated_at
        OR NEW.generated_by IS DISTINCT FROM OLD.generated_by
        OR NEW.version <> OLD.version + 1 OR NEW.refreshed_at IS NULL
        OR (OLD.refreshed_at IS NOT NULL AND NEW.refreshed_at < OLD.refreshed_at) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'timesheet_generation_guard',
            MESSAGE = 'a timesheet generation changes only by a refresh';
    END IF;
    RETURN NEW;
END
$fn$;

CREATE TRIGGER timesheet_generation_guard
    BEFORE INSERT OR UPDATE OR DELETE ON people.timesheet_generation
    FOR EACH ROW EXECUTE FUNCTION people.timesheet_generation_guard();

-- A timesheet is inserted at revision 1; its only change moves to the next revision (with that
-- revision's totals, enforced by timesheet_current); never deleted.
CREATE FUNCTION people.timesheet_guard() RETURNS trigger
    LANGUAGE plpgsql
AS $fn$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'timesheet_immutable',
            MESSAGE = 'a timesheet is never deleted';
    END IF;
    IF TG_OP = 'INSERT' THEN
        IF NEW.current_revision <> 1 OR NEW.updated_at <> NEW.created_at THEN
            RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'timesheet_guard',
                MESSAGE = 'a timesheet starts at revision 1';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id OR NEW.id IS DISTINCT FROM OLD.id
        OR NEW.generation_id IS DISTINCT FROM OLD.generation_id
        OR NEW.employee_id IS DISTINCT FROM OLD.employee_id
        OR NEW.site_id IS DISTINCT FROM OLD.site_id OR NEW.week_start IS DISTINCT FROM OLD.week_start
        OR NEW.status IS DISTINCT FROM OLD.status OR NEW.created_at IS DISTINCT FROM OLD.created_at
        OR NEW.current_revision <> OLD.current_revision + 1 OR NEW.updated_at < OLD.updated_at THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'timesheet_guard',
            MESSAGE = 'a timesheet changes only to its next revision';
    END IF;
    RETURN NEW;
END
$fn$;

CREATE TRIGGER timesheet_guard
    BEFORE INSERT OR UPDATE OR DELETE ON people.timesheet
    FOR EACH ROW EXECUTE FUNCTION people.timesheet_guard();

-- Revisions are contiguous: revision n needs revision n - 1 of the same timesheet.
CREATE FUNCTION people.timesheet_revision_guard() RETURNS trigger
    LANGUAGE plpgsql
AS $fn$
DECLARE
    v_latest integer;
BEGIN
    SELECT max(revision) INTO v_latest FROM people.timesheet_revision
    WHERE tenant_id = NEW.tenant_id AND timesheet_id = NEW.timesheet_id;
    IF NEW.revision IS DISTINCT FROM coalesce(v_latest, 0) + 1 THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'timesheet_revision_sequence',
            MESSAGE = 'a timesheet revision follows the latest one';
    END IF;
    RETURN NEW;
END
$fn$;

CREATE TRIGGER timesheet_revision_guard
    BEFORE INSERT ON people.timesheet_revision
    FOR EACH ROW EXECUTE FUNCTION people.timesheet_revision_guard();

-- Deferred, per revision: its totals are exactly its rows' counts and sum, and the timesheet's
-- current revision is its latest one.
CREATE FUNCTION people.timesheet_revision_exact() RETURNS trigger
    LANGUAGE plpgsql
AS $fn$
DECLARE
    v_header people.timesheet_revision%ROWTYPE;
    v_rows   integer;
    v_ready  integer;
    v_miss   integer;
    v_open   integer;
    v_chg    integer;
    v_worked bigint;
    v_latest integer;
    v_current integer;
BEGIN
    SELECT * INTO v_header FROM people.timesheet_revision
    WHERE tenant_id = NEW.tenant_id AND timesheet_id = NEW.timesheet_id
      AND revision = NEW.revision;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'timesheet_revision_exact',
            MESSAGE = 'a timesheet row needs its revision';
    END IF;
    SELECT count(*), count(*) FILTER (WHERE state = 'READY'),
           count(*) FILTER (WHERE state = 'MISSING_ATTENDANCE'),
           count(*) FILTER (WHERE state = 'OPEN_ATTENDANCE'),
           count(*) FILTER (WHERE state = 'SOURCE_CHANGED'),
           coalesce(sum(worked_minutes), 0)
      INTO v_rows, v_ready, v_miss, v_open, v_chg, v_worked
    FROM people.timesheet_row
    WHERE tenant_id = NEW.tenant_id AND timesheet_id = NEW.timesheet_id
      AND revision = NEW.revision;
    IF v_rows <> v_header.row_count OR v_ready <> v_header.ready_rows
        OR v_miss <> v_header.missing_rows OR v_open <> v_header.open_rows
        OR v_chg <> v_header.changed_rows OR v_worked <> v_header.worked_minutes THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'timesheet_revision_exact',
            MESSAGE = 'a timesheet revision header differs from its rows';
    END IF;
    SELECT max(revision) INTO v_latest FROM people.timesheet_revision
    WHERE tenant_id = NEW.tenant_id AND timesheet_id = NEW.timesheet_id;
    SELECT current_revision INTO v_current FROM people.timesheet
    WHERE tenant_id = NEW.tenant_id AND id = NEW.timesheet_id;
    IF v_current IS DISTINCT FROM v_latest THEN
        RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'timesheet_revision_exact',
            MESSAGE = 'a timesheet shows its latest revision';
    END IF;
    RETURN NULL;
END
$fn$;

CREATE CONSTRAINT TRIGGER timesheet_revision_exact
    AFTER INSERT ON people.timesheet_revision
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW EXECUTE FUNCTION people.timesheet_revision_exact();
CREATE CONSTRAINT TRIGGER timesheet_row_exact
    AFTER INSERT ON people.timesheet_row
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW EXECUTE FUNCTION people.timesheet_revision_exact();
